DO $security$
DECLARE tab text;
BEGIN
  FOREACH tab IN ARRAY ARRAY['snapshots','discovery_attempts','validation_assessments'] LOOP
    EXECUTE format('ALTER TABLE gridex_received_sources.%I ENABLE ROW LEVEL SECURITY', tab);
