-- The established accepted transport journal returns before fresh authority.
-- Fresh paths consume actual private duplicate ACK IDs only. Never send here.
DO $transport$ DECLARE schema_name text;definition text;needle text;BEGIN
 FOREACH schema_name IN ARRAY ARRAY['gridex_ediel_transport','gridex_outbound_dispatch'] LOOP
  definition:=pg_get_functiondef(format('%I.mutate_v1(jsonb)',schema_name)::regprocedure);
  -- Use an internal predecessor without moving the public/current function OID.
  EXECUTE replace(definition,format('%I.mutate_v1(',schema_name),format('%I.mutate_before_duplicate_protocol_v1(',schema_name));
  definition:=format('CREATE OR REPLACE FUNCTION %I.mutate_v1(p_input jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $body$DECLARE r jsonb;BEGIN PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();PERFORM gridex_bilateral_prodat.lock_source_receipts_v1();r:=%I.mutate_before_duplicate_protocol_v1(p_input);IF p_input->>''action'' IN(''prepare'',''enter'') AND r->>''proceed''=''true'' THEN PERFORM gridex_ediel_duplicate_responses.require_transport_v1((p_input->>''companyId'')::uuid,(p_input->>''messageId'')::uuid,(p_input->>''actorUserId'')::uuid);END IF;RETURN r;END$body$',schema_name,schema_name);
  EXECUTE definition;EXECUTE format('REVOKE ALL ON FUNCTION %I.mutate_before_duplicate_protocol_v1(jsonb) FROM PUBLIC,anon,authenticated,service_role',schema_name);
 END LOOP;
END $transport$;

DO $$DECLARE item record;p record;after_p record;body text;definition text;guard text;begin_at integer;returns integer;BEGIN
 FOR item IN SELECT * FROM(VALUES
  ('public.ediel_supply_rescission_scope_v1(uuid,uuid,jsonb)','read',2),
  ('public.ediel_archive_supply_rescission_v1(uuid,uuid,jsonb)','archive',2),
  ('public.ediel_review_supply_rescission_v1(uuid,uuid,uuid,jsonb)','review',3),
  ('public.ediel_read_supply_rescission_artifact_v1(uuid,uuid,uuid,boolean)','read',1)
 ) v(signature,phase,expected_returns) LOOP
  SELECT pr.*,l.lanname INTO p FROM pg_proc pr JOIN pg_language l ON l.oid=pr.prolang WHERE pr.oid=to_regprocedure(item.signature);
  IF p.oid IS NULL OR p.lanname<>'plpgsql' OR p.prosecdef IS NOT TRUE OR position('gridex_supply_rescission.actor_v1(p_company_id,p_actor_user_id,' IN p.prosrc)=0 OR position('require_intake_session_v1' IN p.prosrc)>0 OR position('gridex_intake_session_result_v1' IN p.prosrc)>0 THEN
   RAISE EXCEPTION 'supply_rescission_intake_forward_owner_shape_changed: %',item.signature;
  END IF;
  SELECT count(*) INTO returns FROM regexp_matches(p.prosrc,'\mRETURN\M([^;]+);','g');
  IF position('BEGIN' IN p.prosrc)=0 OR position('DECLARE' IN p.prosrc)=0 OR returns<>item.expected_returns THEN RAISE EXCEPTION 'supply_rescission_intake_forward_return_shape_changed: %',item.signature;END IF;
  guard:=format('PERFORM gridex_supply_rescission.require_intake_session_v1(p_company_id,p_actor_user_id,%L);',item.phase);
  -- Evaluate each complete original expression before the terminal guard:
  -- review replay's expression itself performs current-mandate native reads.
  -- All bounded original expressions contain no statement terminator literals.
  body:=regexp_replace(p.prosrc,'\mRETURN\M([^;]+);','gridex_intake_session_result_v1 :=\1; '||guard||' RETURN gridex_intake_session_result_v1;','g');
  body:=overlay(body PLACING 'DECLARE gridex_intake_session_result_v1 jsonb;' FROM position('DECLARE' IN body) FOR 7);
  begin_at:=position('BEGIN' IN body);
  body:=overlay(body PLACING 'BEGIN '||guard FROM begin_at FOR 5);
  definition:=pg_get_functiondef(p.oid);
  IF position(p.prosrc IN definition)=0 THEN RAISE EXCEPTION 'supply_rescission_intake_forward_definition_changed: %',item.signature;END IF;
  EXECUTE replace(definition,p.prosrc,body);
  SELECT * INTO after_p FROM pg_proc WHERE oid=to_regprocedure(item.signature);
  IF after_p.oid<>p.oid OR after_p.proowner<>p.proowner OR after_p.proconfig IS DISTINCT FROM p.proconfig OR after_p.prosecdef IS DISTINCT FROM p.prosecdef OR after_p.provolatile<>p.provolatile OR after_p.proargtypes<>p.proargtypes OR after_p.prorettype<>p.prorettype OR after_p.proargnames IS DISTINCT FROM p.proargnames OR after_p.proargdefaults IS DISTINCT FROM p.proargdefaults OR after_p.proacl IS DISTINCT FROM p.proacl THEN
   RAISE EXCEPTION 'supply_rescission_intake_forward_catalog_changed: %',item.signature;
  END IF;
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon,authenticated,service_role',item.signature);
  EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO authenticated',item.signature);
 END LOOP;
END$$;

DO $$DECLARE f record;copy text;port record;body text;BEGIN
 FOR port IN SELECT * FROM (VALUES
  ('public.ediel_contract_intake_scope_v1(uuid,uuid,uuid,text,text)','gridex_contract_source_intake.terminal_scope_body_v1',
   'PERFORM gridex_contract_source_intake.actor_v1(p_company_id,p_actor_user_id,''archive'',p_kind);'),
