DO $staff_retention_read$
DECLARE
 migration_role text := current_user;
 owner_id oid := to_regrole('gridex_ediel_retention_owner')::oid;
 namespace_id oid := to_regnamespace('gridex_ediel_retention')::oid;
 table_name text;
